package com.littlemakers.village.rendercheck;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;
/** Isolated device integration checks for real quest UI controls, meshes, wallet and saves. */
public final class QuestCheck extends Instrumentation {
 private Activity activity;private File out;private int passed;
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 Object field(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 Object call(Object o,String n,Class<?>[]types,Object...args)throws Exception{Method m=o.getClass().getDeclaredMethod(n,types);m.setAccessible(true);return m.invoke(o,args);}
 void ui(Runnable r){java.util.concurrent.atomic.AtomicReference<Throwable>failure=new java.util.concurrent.atomic.AtomicReference<>();runOnMainSync(()->{try{r.run();}catch(Throwable e){failure.set(e);}});waitForIdleSync();if(failure.get()!=null)throw new AssertionError("UI operation failed",failure.get());}
 void invoke(String name,Class<?>[]types,Object...args){ui(()->{try{call(activity,name,types,args);}catch(Exception e){throw new RuntimeException(e);}});}
 Button find(View v,String label){if(v instanceof Button&&label.equals(((Button)v).getText().toString()))return(Button)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){Button b=find(((ViewGroup)v).getChildAt(i),label);if(b!=null)return b;}return null;}
 void click(String s){ui(()->{Button b=find(activity.getWindow().getDecorView(),s);if(b==null)throw new AssertionError("Button missing: "+s);b.performClick();});}
 interface Condition{boolean ok()throws Exception;}
 void waitFor(Condition c,String s)throws Exception{long end=SystemClock.uptimeMillis()+20000;while(SystemClock.uptimeMillis()<end){if(c.ok())return;SystemClock.sleep(100);}throw new AssertionError("Timeout "+s);}
 Object q()throws Exception{return field(activity,"quest");}
 int integer(Object o,String name)throws Exception{return(Integer)call(o,name,new Class[0]);}
 void screen(String name)throws Exception{waitForIdleSync();SystemClock.sleep(200);waitFor(()->field(activity,"stage")!=null&&(Long)field(field(activity,"stage"),"renderedFrames")>1,"mesh rendering");Bitmap b=getUiAutomation().takeScreenshot();if(b==null)throw new AssertionError("No screenshot");try(FileOutputStream f=new FileOutputStream(new File(out,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,f);}b.recycle();passed++;Bundle status=new Bundle();status.putString("case",name);sendStatus(1,status);}
 @Override public void onStart(){Bundle result=new Bundle();try{out=new File(getTargetContext().getFilesDir(),"quest-check");out.mkdirs();getTargetContext().getSharedPreferences("learning_quests",0).edit().clear().putInt("tier",2).commit();getTargetContext().getSharedPreferences("family",0).edit().putString("theme","light").putBoolean("reduce_motion",false).commit();activity=startActivitySync(new Intent().setClassName("com.littlemakers.village","com.littlemakers.village.nativeapp.QuestActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();click("Number Guardians");Object wallet=field(activity,"wallet");int coins=integer(wallet,"coins"),stars=integer(wallet,"stars");int wrong=integer(q(),"answer")+1;click(""+wrong);click(""+wrong);if((Integer)field(q(),"tier")!=1)throw new AssertionError("Adaptive scaffolding failed");screen("guardian-adaptive");click(""+integer(q(),"answer"));if(!(Boolean)field(q(),"won"))throw new AssertionError("Math not won");if(integer(wallet,"coins")!=coins+5||integer(wallet,"stars")!=stars+1)throw new AssertionError("Wallet reward missing");screen("guardian-win");invoke("load",new Class[]{int.class},0);if(integer(wallet,"coins")!=coins+5)throw new AssertionError("Duplicate resume reward");click("Next discovery");if((Integer)field(q(),"stage")!=1)throw new AssertionError("Next stage missing");invoke("load",new Class[]{int.class},1);click("Test the balance");if((Boolean)field(q(),"won"))throw new AssertionError("Incorrect balance accepted");for(int i=0;i<integer(q(),"missing");i++)click("+ Add");screen("balance-weights");click("Test the balance");if(!(Boolean)field(q(),"won"))throw new AssertionError("Balance not won");screen("balance-win");invoke("load",new Class[]{int.class},2);click("↑ Forward");click("↶ Left");click("Undo");if(!field(q(),"commands").toString().equals("F"))throw new AssertionError("Undo failed");click("Clear");click("↶ Left");click("↑ Forward");click("Run my robot");waitFor(()->!(Boolean)field(activity,"running"),"blocked route stops");if((Boolean)field(q(),"won"))throw new AssertionError("Blocked route won");screen("robot-clue");click("Clear");for(int i=0;i<3;i++)click("↑ Forward");click("↷ Right");for(int i=0;i<3;i++)click("↑ Forward");click("Run my robot");waitFor(()->(Boolean)field(q(),"won"),"robot run completes");screen("robot-win");if(integer(wallet,"coins")!=coins+15||integer(wallet,"stars")!=stars+3)throw new AssertionError("Shared reward totals wrong");ActivityMonitor mon=addMonitor("com.littlemakers.village.nativeapp.QuestActivity",null,false);ui(()->activity.recreate());Activity next=waitForMonitorWithTimeout(mon,15000);removeMonitor(mon);if(next==null)throw new AssertionError("Recreation failed");activity=next;waitForIdleSync();if(!(Boolean)field(q(),"won")||!field(q(),"commands").toString().equals("FFFRFFF"))throw new AssertionError("Save did not survive recreation");screen("robot-restored");getTargetContext().getSharedPreferences("family",0).edit().putString("theme","dark").putBoolean("reduce_motion",true).commit();invoke("load",new Class[]{int.class},1);Object theme=field(activity,"theme");Button nextButton=find(activity.getWindow().getDecorView(),"Next discovery");if(nextButton.getCurrentTextColor()!=(Integer)field(theme,"text"))throw new AssertionError("Button did not inherit dark text");screen("quest-dark-reduced");ui(()->activity.finish());getTargetContext().getSharedPreferences("family",0).edit().putString("theme","light").putBoolean("reduce_motion",false).commit();result.putString("stream","PASS "+passed+" quest device checks: adaptive answers, balance, robot sequence/undo/collision, three wallet awards, idempotency, recreation and dark reduced-motion meshes\n");finish(Activity.RESULT_OK,result);}catch(Throwable e){result.putString("stream","FAIL after "+passed+": "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
}
